[
  {
    "severity": "P0毁容级",
    "category": "ua-default-style",
    "description": "底部消息输入框的附件上传按钮「+」和发送按钮（纸飞机图标）使用浏览器原生 button 样式：圆形灰底、系统默认边框/聚焦环，与「酱园琥珀」暖纸+酱色设计语言完全冲突。",
    "suggestion": "将这两个按钮重做为符合设计语言的扁平圆角按钮，背景使用酱色或琥珀色，去除原生灰底与系统聚焦环。"
  },
  {
    "severity": "P0毁容级",
    "category": "ua-default-style",
    "description": "快捷指令区的 6 个胶囊按钮（问企业档案/问供应链/语音/拍照/相册/文件）整体外观接近浏览器原生按钮：白底、1px 浅灰描边、轻微系统阴影，未呈现「酱园琥珀」印章/烫蜡质感。",
    "suggestion": "替换为暖米色底+酱色细描边+琥珀点缀的圆角卡片，使用衬线/印章字体而非系统字体。"
  },
  {
    "severity": "P0毁容级",
    "category": "ua-default-style",
    "description": "两个「问企业档案」「问供应链」提示胶囊中的圆点（bullet）使用系统默认橙色 bullet marker，与设计语言冲突。",
    "suggestion": "改用酱色或琥珀色实心圆点（<span> 圆点元素 + 自定义 color），并保持与按钮配色统一。"
  },
  {
    "severity": "P1明显",
    "category": "ua-default-style",
    "description": "顶部「+」新建会话按钮使用浏览器默认圆角灰底按钮样式，无品牌色。",
    "suggestion": "重做为酱色填充圆角按钮或琥珀描边圆形图标按钮。"
  },
  {
    "severity": "P1明显",
    "category": "ua-default-style",
    "description": "附件预览缩略图「vfy-wl0-01-home-375..」的文件关闭按钮（×）为系统默认灰色 × 图标与浅灰底。",
    "suggestion": "使用酱色描边圆形按钮，× 图标用琥珀色，并按「印章」造型处理。"
  },
  {
    "severity": "P1明显",
    "category": "typography",
    "description": "「我是企业数据助手」标题使用系统默认无衬线粗体字，未采用设计语言中强调的印章/衬线字体，与顶部「新会话」形成风格断层。",
    "suggestion": "标题换用衬线/印章体（思源宋体/方正印章体），并使用酱色强化仪式感。"
  },
  {
    "severity": "P1明显",
    "category": "typography",
    "description": "「数据」徽标下的「企业数据助手」副标题字号偏小且字重过轻，与上方徽标对比失衡。",
    "suggestion": "提升副标题字重至 500/600，并补充微小琥珀色点状装饰或留白节奏。"
  },
  {
    "severity": "P1明显",
    "category": "inconsistency",
    "description": "「问企业档案」和「问供应链」在提示胶囊中是带 bullet 的文字条目，但在下方「快捷指令」区又变成了带图标的按钮，同一概念在两处视觉形态完全不同。",
    "suggestion": "统一为同一种胶囊形态（图标+文字+酱色描边），避免同一功能双形态出现。"
  },
  {
    "severity": "P1明显",
    "category": "contrast",
    "description": "快捷指令区 6 个按钮的文字（语音/拍照/相册/文件/问企业档案/问供应链）颜色为系统默认深灰，对暖米色底对比度尚可，但图标颜色偏淡，识别度低。",
    "suggestion": "图标统一用酱色，文字用深棕红（#5A2A1F 一类），提升图标与背景对比。"
  },
  {
    "severity": "P2瑕疵",
    "category": "spacing",
    "description": "顶部 header 与「我是企业数据助手」主区之间留白过大（约 80px），而快捷指令区到输入框距离过近，节奏失衡。",
    "suggestion": "收紧 header 与 Hero 区距离，扩展底部输入区上方呼吸空间至 24–32px。"
  },
  {
    "severity": "P2瑕疵",
    "category": "misalign",
    "description": "「新会话」标题在 header 中未严格水平居中，偏向右侧「+」按钮方向。",
    "suggestion": "用 flex 居中并让左右返回/新增按钮等宽占位，保证标题精确居中。"
  },
  {
    "severity": "P2瑕疵",
    "category": "other",
    "description": "「表」字圆形印章装饰元素尺寸偏大、压住标题空间，且印章描边为默认深灰而非酱色烫蜡效果，削弱品牌识别。",
    "suggestion": "印章缩为 56–64px，描边与底色使用酱色渐变，模仿真实烫蜡印章质感。"
  }
]
